def citation_authors(names):
    values=[]
    for name in names:
        if ',' not in name:values.append(name);continue
        surname,given=name.split(',',1)
        if given.strip()=='Annemarie' and surname.endswith('thge'):surname='Bäthge'
        initials=' '.join(x[0]+'.' for x in given.strip().split() if x);values.append(surname+', '+initials)
    return ', '.join(values[:-1])+', & '+values[-1] if len(values)>1 else values[0]
