    w.table('Table '+prefix+'.1','National full record observed storage trends',['Storage','Months','Sen mm/year','95 percent interval'],[['TWSA',235,'−7.46','−9.60 to −5.69'],['GWSA',223,'−6.82','−8.64 to −5.13']])
    w.h('Climate emulator verification');w.body('emulator_results');w.table('Table '+prefix+'.2','National test performance against naturalized model output',['Target','NSE','Anomaly NSE','RMSE mm'],[[x['variable'],fmt(x['NSE'],3),fmt(x['deseasonalized_NSE'],3),fmt(x['RMSE_mm'])] for x in EM])
