    w.h('Hydrological benchmarks');w.body('benchmark_results');w.fig('Figure '+prefix+'.2','Observed and modeled national storage on common support',FIG/'national_naturalized_human_comparison.png')
    w.h('Climate residual and model discrepancy');w.body('residual_results')
    w.table('Table '+prefix+'.3','Common record seasonal Sen component slopes in millimetres per year',['Component','TWSA','GWSA'],[[name,fmt(national('national_component_trends','TWSA',component=key)['sen_slope_mm_year']),fmt(national('national_component_trends','GWSA',component=key)['sen_slope_mm_year'])] for key,name in [('observed_mm','Observed'),('climate_mm','Naturalized climate'),('modeled_human_mm','Modeled direct human'),('residual_mm','Observed residual'),('discrepancy_mm','Model discrepancy')]])
    w.para('The component Sen slopes are not additive. Table values summarize each series robustly; the downloadable fixed-month OLS table provides an additive point-trend decomposition on the same dates.')
    w.fig('Figure '+prefix+'.3','Residual and modeled human effect with remaining discrepancy',FIG/'national_residual_and_model_discrepancy.png')
    w.fig('Figure '+prefix+'.4','Basin climate and residual trends at shared coarse spatial support',FIG/'all_basin_climate_residual_trends.png',5.75)
    w.h('Groundwater evidence');w.body('well_results');w.table('Table '+prefix+'.4','Annual residual association with observed groundwater head',['Residual','Years','Raw r','Climate controlled r'],[[x['variable'],x['n'],fmt(x['r'],3),fmt(x['partial_r_controlling_natural_climate'],3)] for x in GW])
